# Standalone deterministic verifier. No imports, no I/O, no floats, no prints.
# Fail-closed: verify(witness) RAISES on any failed check. Exact integers only.

def binom3(n):
    return (n * (n - 1) * (n - 2)) // 6

def verify(witness):
    N = witness['N']
    m_infeasible = witness['m_infeasible']

    # (1) structural sanity on the witness itself
    if N != 27:
        raise ValueError('unexpected N')
    if m_infeasible != 7:
        raise ValueError('unexpected m_infeasible')

    # (2) exact ceiling-cube-root: ceil((6N)^(1/3)) == 6
    #     iff 5^3 < 6N <= 6^3 in exact integers
    if 6 * N <= 5 * 5 * 5:
        raise ValueError('lower cube check failed')
    if 6 * N > 6 * 6 * 6:
        raise ValueError('upper cube check failed')

    # (3) exact pigeonhole: C(m+2,3) triples vs 3N-2 attainable sums 3..3N
    if binom3(m_infeasible + 2) <= 3 * N - 2:
        raise ValueError('pigeonhole obstruction does not apply')

    # (4) the infeasible size 7 strictly exceeds the bound value 6
    if m_infeasible <= 6:
        raise ValueError('bound not exceeded')

    return True
